    "# The RPG module's methods for RPG Maker VX Ace (RGSS3), written from the behavior the help's RPG pages describe.\012"
    "# rpg3_data.rb, loaded first, defines the data classes and their attributes.\012"
    "module RPG\012"
    "  class AudioFile\012"
    "    def initialize(name = '', volume = 100, pitch = 100)\012"
    "      @name = name\012"
    "      @volume = volume\012"
    "      @pitch = pitch\012"
    "    end\012"
    "  end\012"
    "\012"
    "  # BGM and BGS remember what played last and where, so a scene can stop the music and resume it later.\012"
    "  class BGM < AudioFile\012"
    "    attr_accessor :pos\012"
    "\012"
    "    def play(pos = 0)\012"
    "      if @name.empty\077\012"
    "        Audio.bgm_stop\012"
    "        @@last = BGM.new\012"
    "      else\012"
    "        Audio.bgm_play(\042Audio/BGM/#{@name}\042, @volume, @pitch, pos)\012"
    "        @@last = clone\012"
    "      end\012"
    "    end\012"
    "\012"
    "    def replay = play(@pos || 0)\012"
    "\012"
    "    def self.stop\012"
    "      Audio.bgm_stop\012"
    "      @@last = BGM.new\012"
    "    end\012"
    "\012"
    "    def self.fade(time)\012"
    "      Audio.bgm_fade(time)\012"
    "      @@last = BGM.new\012"
    "    end\012"
    "\012"
    "    def self.last\012"
    "      @@last.pos = Audio.bgm_pos\012"
    "      @@last\012"
    "    end\012"
    "\012"
    "    @@last = BGM.new\012"
    "  end\012"
    "\012"
    "  class BGS < AudioFile\012"
    "    attr_accessor :pos\012"
    "\012"
    "    def play(pos = 0)\012"
    "      if @name.empty\077\012"
    "        Audio.bgs_stop\012"
    "        @@last = BGS.new\012"
    "      else\012"
    "        Audio.bgs_play(\042Audio/BGS/#{@name}\042, @volume, @pitch, pos)\012"
    "        @@last = clone\012"
    "      end\012"
    "    end\012"
    "\012"
    "    def replay = play(@pos || 0)\012"
    "\012"
    "    def self.stop\012"
    "      Audio.bgs_stop\012"
    "      @@last = BGS.new\012"
    "    end\012"
    "\012"
    "    def self.fade(time)\012"
    "      Audio.bgs_fade(time)\012"
    "      @@last = BGS.new\012"
    "    end\012"
    "\012"
    "    def self.last\012"
    "      @@last.pos = Audio.bgs_pos\012"
    "      @@last\012"
    "    end\012"
    "\012"
    "    @@last = BGS.new\012"
    "  end\012"
    "\012"
    "  class ME < AudioFile\012"
    "    def play\012"
    "      if @name.empty\077 then Audio.me_stop\012"
    "      else Audio.me_play(\042Audio/ME/#{@name}\042, @volume, @pitch)\012"
    "      end\012"
    "    end\012"
    "\012"
    "    def self.stop = Audio.me_stop\012"
    "    def self.fade(time) = Audio.me_fade(time)\012"
    "  end\012"
    "\012"
    "  class SE < AudioFile\012"
    "    def play\012"
    "      Audio.se_play(\042Audio/SE/#{@name}\042, @volume, @pitch) unless @name.empty\077\012"
    "    end\012"
    "\012"
    "    def self.stop = Audio.se_stop\012"
    "  end\012"
    "\012"
    "  class Animation\012"
    "    def to_screen\077 = @position == 3\012"
    "  end\012"
    "\012"
    "  class Weapon\012"
    "    def performance = params[2] + params[4] + params.sum\012"
    "  end\012"
    "\012"
    "  class Armor\012"
    "    def performance = params[3] + params[5] + params.sum\012"
    "  end\012"
    "\012"
    "  class Class\012"
    "    # Total experience for a level from the class's four curve settings: base, extra, and the two acceleration terms.\012"
    "    def exp_for_level(level)\012"
    "      lv = level.to_f\012"
    "      base, extra, accel_a, accel_b = @exp_params.map(&:to_f)\012"
    "      (base * ((lv - 1) ** (0.9 + accel_a / 250)) * lv * (lv + 1) / (6 + lv ** 2 / 50 / accel_b) + (lv - 1) * extra).round.to_i\012"
    "    end\012"
    "  end\012"
    "\012"
    "  class CommonEvent\012"
    "    def autorun\077 = @trigger == 1\012"
    "    def parallel\077 = @trigger == 2\012"
    "  end\012"
    "\012"
    "  class Item\012"
    "    def key_item\077 = @itype_id == 2\012"
    "  end\012"
    "\012"
    "  class UsableItem\012"
    "    def for_opponent\077 = [1, 2, 3, 4, 5, 6].include\077(@scope)\012"
    "    def for_friend\077 = [7, 8, 9, 10, 11].include\077(@scope)\012"
    "    def for_dead_friend\077 = [9, 10].include\077(@scope)\012"
    "    def for_user\077 = @scope == 11\012"
    "    def for_one\077 = [1, 3, 7, 9, 11].include\077(@scope)\012"
    "    def for_random\077 = [3, 4, 5, 6].include\077(@scope)\012"
    "    def number_of_targets = for_random\077 \077 @scope - 2 : 0\012"
    "    def for_all\077 = [2, 8, 10].include\077(@scope)\012"
    "    def need_selection\077 = [1, 7, 9].include\077(@scope)\012"
    "    def battle_ok\077 = [0, 1].include\077(@occasion)\012"
    "    def menu_ok\077 = [0, 2].include\077(@occasion)\012"
    "    def certain\077 = @hit_type == 0\012"
    "    def physical\077 = @hit_type == 1\012"
    "    def magical\077 = @hit_type == 2\012"
    "\012"
    "    class Damage\012"
    "      def none\077 = @type == 0\012"
    "      def to_hp\077 = [1, 3, 5].include\077(@type)\012"
    "      def to_mp\077 = [2, 4, 6].include\077(@type)\012"
    "      def recover\077 = [3, 4].include\077(@type)\012"
    "      def drain\077 = [5, 6].include\077(@type)\012"
    "      def sign = recover\077 \077 -1 : 1\012"
    "\012"
    "      # The damage formula from the database, evaluated with the user as `a`, the target as `b` and the game's\012"
    "      # variables as `v`. A formula that fails counts as zero, as on PC.\012"
    "      def eval(a, b, v)\012"
    "        [Kernel.eval(@formula), 0].max * sign\012"
    "      rescue StandardError\012"
    "        0\012"
    "      end\012"
    "    end\012"
    "  end\012"
    "end\012"
    "\012";
